 ('M3',16,'ต 2.2','FL-M3-16','เปรียบเทียบและอธิบายความเหมือนและความแตกต่างระหว่างการออกเสียงประโยคชนิดต่าง ๆ และการลำดับคำตามโครงสร้างประโยคของภาษาต่างประเทศและภาษาไทย','must_know','ต 2.2 ม.3/1'),
 ('M3',17,'ต 2.2','FL-M3-17','เปรียบเทียบและอธิบายความเหมือนและความแตกต่างระหว่างชีวิตความเป็นอยู่และวัฒนธรรมของเจ้าของภาษากับของไทย และนำไปใช้อย่างเหมาะสม','must_know','ต 2.2 ม.3/2'),
 ('M3',18,'ต 3.1','FL-M3-18','ค้นคว้า รวบรวม และสรุปข้อมูล/ข้อเท็จจริงที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่นจากแหล่งเรียนรู้ และนำเสนอด้วยการพูดและการเขียน','must_know','ต 3.1 ม.3/1'),
 ('M3',19,'ต 4.1','FL-M3-19','ใช้ภาษาสื่อสารในสถานการณ์จริง/สถานการณ์จำลองที่เกิดขึ้นในห้องเรียน สถานศึกษา ชุมชน และสังคม','must_know','ต 4.1 ม.3/1'),
 ('M3',20,'ต 4.2','FL-M3-20','ใช้ภาษาต่างประเทศในการสืบค้น/ค้นคว้า รวบรวม และสรุปความรู้/ข้อมูลต่าง ๆ จากสื่อและแหล่งการเรียนรู้ต่าง ๆ ในการศึกษาต่อและประกอบอาชีพ','must_know','ต 4.2 ม.3/1'),
 ('M3',21,'ต 4.2','FL-M3-21','เผยแพร่/ประชาสัมพันธ์ข้อมูลข่าวสารของโรงเรียน ชุมชน และท้องถิ่นเป็นภาษาต่างประเทศ','should_know','ต 4.2 ม.3/2'),
 ('M4-M6',1,'ต 1.1','FL-M46-01','ปฏิบัติตามคำแนะนำในคู่มือการใช้งานต่าง ๆ คำชี้แจง คำอธิบาย และคำบรรยายที่ฟังและอ่าน','must_know','ต 1.1 ม.4-6/1'),
 ('M4-M6',2,'ต 1.1','FL-M46-02','อ่านออกเสียงข้อความ ข่าว ประกาศ โฆษณา บทร้อยกรอง และบทละครสั้น ๆ ถูกต้องตามหลักการอ่าน','must_know','ต 1.1 ม.4-6/2'),
 ('M4-M6',3,'ต 1.1','FL-M46-03','อธิบายและเขียนประโยคและข้อความให้สัมพันธ์กับสื่อที่ไม่ใช่ความเรียงรูปแบบต่าง ๆ ที่อ่าน รวมทั้งระบุและเขียนสื่อที่ไม่ใช่ความเรียงรูปแบบต่าง ๆ ให้สัมพันธ์กับประโยคและข้อความที่ฟังหรืออ่าน','must_know','ต 1.1 ม.4-6/3'),
 ('M4-M6',4,'ต 1.1','FL-M46-04','จับใจความสำคัญ วิเคราะห์ความ สรุปความ ตีความ และแสดงความคิดเห็นจากการฟังและอ่านเรื่องที่เป็นสารคดีและบันเทิงคดี พร้อมทั้งให้เหตุผลและยกตัวอย่างประกอบ','must_know','ต 1.1 ม.4-6/4'),
 ('M4-M6',5,'ต 1.2','FL-M46-05','สนทนาและเขียนโต้ตอบข้อมูลเกี่ยวกับตนเอง เรื่องต่าง ๆ ใกล้ตัว ประสบการณ์ สถานการณ์ ข่าว/เหตุการณ์ ประเด็นที่อยู่ในความสนใจของสังคม และสื่อสารอย่างต่อเนื่องและเหมาะสม','must_know','ต 1.2 ม.4-6/1'),
 ('M4-M6',6,'ต 1.2','FL-M46-06','เลือกและใช้คำขอร้อง ให้คำแนะนำ คำชี้แจง คำอธิบายอย่างคล่องแคล่ว','must_know','ต 1.2 ม.4-6/2'),
 ('M4-M6',7,'ต 1.2','FL-M46-07','พูดและเขียนแสดงความต้องการ เสนอ ตอบรับและปฏิเสธการให้ความช่วยเหลือในสถานการณ์จำลองหรือสถานการณ์จริงอย่างเหมาะสม','must_know','ต 1.2 ม.4-6/3'),
 ('M4-M6',8,'ต 1.2','FL-M46-08','พูดและเขียนเพื่อขอและให้ข้อมูล บรรยาย อธิบาย เปรียบเทียบ และแสดงความคิดเห็นเกี่ยวกับเรื่อง/ประเด็น/ข่าว/เหตุการณ์ที่ฟังและอ่านอย่างเหมาะสม','must_know','ต 1.2 ม.4-6/4'),
 ('M4-M6',9,'ต 1.2','FL-M46-09','พูดและเขียนบรรยายความรู้สึกและแสดงความคิดเห็นของตนเองเกี่ยวกับเรื่องต่าง ๆ กิจกรรม ประสบการณ์ และข่าว/เหตุการณ์อย่างมีเหตุผล','must_know','ต 1.2 ม.4-6/5'),
 ('M4-M6',10,'ต 1.3','FL-M46-10','พูดและเขียนนำเสนอข้อมูลเกี่ยวกับตนเอง ประสบการณ์ ข่าว/เหตุการณ์ เรื่องและประเด็นต่าง ๆ ที่อยู่ในความสนใจของสังคม','must_know','ต 1.3 ม.4-6/1'),
 ('M4-M6',11,'ต 1.3','FL-M46-11','พูดและเขียนสรุปใจความสำคัญ/แก่นสาระที่ได้จากการวิเคราะห์เรื่อง กิจกรรม ข่าว เหตุการณ์ และสถานการณ์ตามความสนใจ','must_know','ต 1.3 ม.4-6/2'),
 ('M4-M6',12,'ต 1.3','FL-M46-12','พูดและเขียนแสดงความคิดเห็นเกี่ยวกับกิจกรรม ประสบการณ์ และเหตุการณ์ ทั้งในท้องถิ่น สังคม และโลก พร้อมทั้งให้เหตุผลและยกตัวอย่างประกอบ','must_know','ต 1.3 ม.4-6/3'),
 ('M4-M6',13,'ต 2.1','FL-M46-13','เลือกใช้ภาษา น้ำเสียง และกิริยาท่าทางเหมาะกับระดับของบุคคล โอกาส และสถานที่ตามมารยาทสังคมและวัฒนธรรมของเจ้าของภาษา','must_know','ต 2.1 ม.4-6/1'),
 ('M4-M6',14,'ต 2.1','FL-M46-14','อธิบาย/อภิปรายวิถีชีวิต ความคิด ความเชื่อ และที่มาของขนบธรรมเนียมและประเพณีของเจ้าของภาษา','should_know','ต 2.1 ม.4-6/2'),
 ('M4-M6',15,'ต 2.1','FL-M46-15','เข้าร่วม แนะนำ และจัดกิจกรรมทางภาษาและวัฒนธรรมอย่างเหมาะสม','should_know','ต 2.1 ม.4-6/3'),
 ('M4-M6',16,'ต 2.2','FL-M46-16','อธิบาย/เปรียบเทียบความแตกต่างระหว่างโครงสร้างประโยค ข้อความ สำนวน คำพังเพย สุภาษิต และบทกลอนของภาษาต่างประเทศและภาษาไทย','must_know','ต 2.2 ม.4-6/1'),
 ('M4-M6',17,'ต 2.2','FL-M46-17','วิเคราะห์/อภิปรายความเหมือนและความแตกต่างระหว่างวิถีชีวิต ความเชื่อ และวัฒนธรรมของเจ้าของภาษากับของไทย และนำไปใช้อย่างมีเหตุผล','should_know','ต 2.2 ม.4-6/2'),
 ('M4-M6',18,'ต 3.1','FL-M46-18','ค้นคว้า/สืบค้น บันทึก สรุป และแสดงความคิดเห็นเกี่ยวกับข้อมูลที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่นจากแหล่งเรียนรู้ต่าง ๆ และนำเสนอด้วยการพูดและการเขียน','must_know','ต 3.1 ม.4-6/1'),
 ('M4-M6',19,'ต 4.1','FL-M46-19','ใช้ภาษาสื่อสารในสถานการณ์จริง/สถานการณ์จำลองที่เกิดขึ้นในห้องเรียน สถานศึกษา ชุมชน และสังคม','must_know','ต 4.1 ม.4-6/1'),
 ('M4-M6',20,'ต 4.2','FL-M46-20','ใช้ภาษาต่างประเทศในการสืบค้น/ค้นคว้า รวบรวม วิเคราะห์ และสรุปความรู้/ข้อมูลต่าง ๆ จากสื่อและแหล่งการเรียนรู้ต่าง ๆ ในการศึกษาต่อและประกอบอาชีพ','must_know','ต 4.2 ม.4-6/1'),
 ('M4-M6',21,'ต 4.2','FL-M46-21','เผยแพร่/ประชาสัมพันธ์ข้อมูลข่าวสารของโรงเรียน ชุมชน และท้องถิ่น/ประเทศชาติเป็นภาษาต่างประเทศ','should_know','ต 4.2 ม.4-6/2')
),
align_seed(grade_code,sequence_no,standard_code,objective_code,priority,official_indicator_code) as (
 select grade_group,sequence_no,standard_code,objective_code,priority,official_indicator_code
 from seed where grade_group<>'M4-M6'
 union all
 select g.grade_code,s.sequence_no,s.standard_code,s.objective_code,s.priority,s.official_indicator_code
 from seed s cross join (values ('M4'),('M5'),('M6')) as g(grade_code)
 where s.grade_group='M4-M6'
),
upserted as (
 insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
 select t.id,s.objective_code,s.indicator_name,
        'Official Thai indicator wording: '||s.indicator_name,
        s.sequence_no,'active'
 from seed s
 join public.learning_subjects sub on sub.code='FOREIGN-LANGUAGES'
 join public.learning_skills sk on sk.subject_id=sub.id
 join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code
 on conflict(topic_id,code) do update
 set name=excluded.name,description=excluded.description,
     sequence_no=excluded.sequence_no,status='active',updated_at=now()
 returning id,topic_id,code
)
insert into public.learning_objective_alignments(
 objective_id,curriculum_id,grade_level_id,sequence_no,required,indicator_classification,notes
)
select u.id,c.id,g.id,s.sequence_no,(s.priority='must_know'),s.priority,
       'Official indicator: '||s.official_indicator_code||'. OBEC 2021 priority classification.'
from align_seed s
join public.learning_subjects sub on sub.code='FOREIGN-LANGUAGES'
join public.learning_skills sk on sk.subject_id=sub.id
join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code
join upserted u on u.topic_id=t.id and u.code=s.objective_code
join public.learning_curricula c on c.code='TH-BASIC-CORE-2008-2017'
join public.learning_grade_levels g on g.curriculum_id=c.id and g.code=s.grade_code and g.status='active'
on conflict(objective_id,curriculum_id,grade_level_id) do update
set sequence_no=excluded.sequence_no,required=excluded.required,
    indicator_classification=excluded.indicator_classification,
    notes=excluded.notes,updated_at=now();